const stormSpiritSheet=new Image();stormSpiritSheet.assetSrc='assets/storm-spirit-v1.png';
function beginStormSpirit(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'stormOrbitTrio',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},angle:Math.atan2(p.y-e.y,p.x-e.x)+Math.PI/3,hits:[false,false,false]};}
function stormOrbPosition(a,i,rotation){let angle=a.angle+i*Math.PI*2/3+rotation;return{x:a.origin.x+Math.cos(angle)*180,y:a.origin.y+Math.sin(angle)*180};}
function stormOrbContact(a,i,from,to,point){let d=dist(a.origin,point);if(d<135-1e-8||d>225+1e-8)return null;let start=a.angle+i*Math.PI*2/3+from,end=a.angle+i*Math.PI*2/3+to,angle=Math.atan2(point.y-a.origin.y,point.x-a.origin.x),offset=((angle-start)%(Math.PI*2)+Math.PI*2)%(Math.PI*2),closest;if(start+offset<=end+1e-8)closest={x:a.origin.x+Math.cos(angle)*180,y:a.origin.y+Math.sin(angle)*180};else{let p1=stormOrbPosition(a,i,from),p2=stormOrbPosition(a,i,to);closest=dist(point,p1)<=dist(point,p2)?p1:p2;}return dist(point,closest)<=45+1e-8?closest:null;}
const stormSpiritAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r6e7')return stormSpiritAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='stormOrbitTrio'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=330&&clear){beginStormSpirit(e);return;}e.state='idle';if(d>800&&!e.aware||d<=200&&clear)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,76*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(e.elapsed>=1.2&&before<3.6){let from=Math.max(0,before-1.2)/2.4*Math.PI*2,to=Math.min(2.4,e.elapsed-1.2)/2.4*Math.PI*2;for(let i=0;i<3;i++){if(a.hits[i])continue;let point=stormOrbContact(a,i,from,to,p);if(point&&lineClear(a.origin,point)&&lineClear(point,p)){a.hits[i]=true;e.struck=true;hurt(34);playSound('impact',point.x,point.y);}}}if(e.elapsed>=4.2){e.attack=null;e.state='idle';e.t=3;}
};
const stormSpiritDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r6e7'||!stormSpiritSheet.complete||!stormSpiritSheet.naturalWidth||!stormSpiritSheet.naturalHeight)return stormSpiritDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='stormOrbitTrio')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.2?1:e.elapsed<3.6?2:3};let q=project(e.x,e.y),sw=stormSpiritSheet.naturalWidth/4,sh=stormSpiritSheet.naturalHeight/3,w=260,h=w*sh/sw,anchor=[.76,.74,.7][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,stormSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(stormSpiritSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const stormSpiritSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r6e7'?165:stormSpiritSizeBase(e);
const stormSpiritGroundBase=drawGroundEffects;drawGroundEffects=()=>{stormSpiritGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e7'):enemies)){let a=e.attack;if(e.species!=='r6e7'||e.hp<=0||a?.pattern!=='stormOrbitTrio'||e.elapsed>=3.6||!visibleAt(e.x,e.y))continue;groundRing(a.origin.x,a.origin.y,135,'#9ad6c5',1);groundRing(a.origin.x,a.origin.y,225,'#bda3dc',1);let rotation=Math.max(0,e.elapsed-1.2)/2.4*Math.PI*2;for(let i=0;i<3;i++){let q=stormOrbPosition(a,i,rotation);if(!a.hits[i]&&lineClear(a.origin,q))groundRing(q.x,q.y,45,e.elapsed<1.2?'#cebce4':'#ffe6a4',2);}}};
const stormSpiritEffectsBase=drawEffects;drawEffects=()=>{stormSpiritEffectsBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r6e7'):enemies)){let a=e.attack;if(e.species!=='r6e7'||e.hp<=0||a?.pattern!=='stormOrbitTrio'||e.elapsed>=3.6||!visibleAt(e.x,e.y))continue;let rotation=Math.max(0,e.elapsed-1.2)/2.4*Math.PI*2;for(let i=0;i<3;i++){let point=stormOrbPosition(a,i,rotation);if(!lineClear(a.origin,point))continue;let q=project(point.x,point.y),spent=a.hits[i];ctx.save();ctx.fillStyle=spent?'#6d718b55':e.elapsed<1.2?'#c8b2e799':'#f5d18c';ctx.strokeStyle=spent?'#8e8a9d':'#fff2c8';ctx.lineWidth=2;ctx.beginPath();ctx.arc(q.x,q.y-22,spent?6:11,0,Math.PI*2);ctx.fill();ctx.stroke();if(!spent){ctx.beginPath();ctx.moveTo(q.x-15,q.y-33);ctx.lineTo(q.x-4,q.y-26);ctx.lineTo(q.x+5,q.y-32);ctx.lineTo(q.x+16,q.y-18);ctx.stroke();}ctx.restore();}}};
